--outer-ai-1
Content-Type: text/javascript; charset=utf-8
Content-Disposition: attachment; filename="fluid.demos.ai.closestNoteImageGenerator"
Content-Description: layer

fluid.def("fluid.demos.ai.closestNoteImageGenerator", {
    // The image generator is dominant - the combined widget is it, with all of its template, state and methods.
    $layers: ["fluid.demos.imageGenerator", "fluid.topLevelWidget"],
    // The note finder is hidden: sharing our view, it renders nothing but its computation continues, and being nested
    // it takes hostBounds from our own shape, so it measures distance to the notes from wherever we are moved.
    noteFinder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            view: "{closestNoteImageGenerator}.view"
        }
    },
    // The closest note's text becomes our prompt, so the input shows it and the button searches it
    state: {
        prompt: "{noteFinder}.noteText"
    }
});
--outer-ai-1
